INSERT INTO `locations` VALUES ('bac-kan-1786190148083','bac-kan','lỗ hổng','discovery',5,'ổn','/api/media/uploads/1786190147987-827738275.jpg','[\"/api/media/uploads/1786190147987-827738275.jpg\",\"/api/media/uploads/1786190147988-434048837.jpg\",\"/api/media/uploads/1786190147989-473814222.jpg\",\"/api/media/uploads/1786190147995-119033817.jpg\",\"/api/media/uploads/1786190147996-591213457.jpg\",\"/api/media/uploads/1786190148000-596191772.jpg\",\"/api/media/uploads/1786190148000-11754400.jpg\",\"/api/media/uploads/1786190148004-858687908.png\",\"/api/media/uploads/1786190148010-464368663.png\",\"/api/media/uploads/1786190148020-675365687.jpg\"]','[\"Khám phá mới\"]','admin','2026-10-06 22:07:56','approved'),('binh-dinh-ky-co-eo-gio-pending','binh-dinh','Eo Gió & Bãi Biển Kỳ Co Quy Nhơn','nature',5,'Cung đường đi bộ ven biển ngoạn mục ôm trọn rặng núi đá kỳ vĩ hướng ra đại dương lộng gió. Bãi Kỳ Co nổi bật với làn nước biển xanh hai màu trong vắt tựa thiên đường Maldives nhiệt đới.','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80','[\"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80\"]','[\"Eo Gió\",\"Kỳ Co\",\"Biển xanh\",\"Quy Nhơn\"]','ngocanh','2026-10-12 22:06:08','pending'),('can-tho-cho-noi-cai-rang-pending','can-tho','Chợ Nổi Cái Răng - Hồn Nước Miền Tây','culture',5,'Nét sinh hoạt văn hóa giao thương sông nước đặc thù duy nhất tại ĐBSCL. Sáng sớm, hàng trăm ghe thuyền chở đầy hoa quả nông sản tụ hội, tiếng máy nổ và câu hò reo mời rộn ràng sông nước.','https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&q=80','[\"https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&q=80\"]','[\"Chợ nổi\",\"Miền Tây\",\"Ẩm thực sông nước\",\"Văn hóa dân dã\"]','viet','2026-10-12 22:06:08','pending'),('cao-bang-1786189823673','cao-bang','aaas','discovery',5,'đẹp','/api/media/uploads/1786189823591-117222233.png','[\"/api/media/uploads/1786189823591-117222233.png\",\"/api/media/uploads/1786189823592-946019585.png\",\"/api/media/uploads/1786189823592-149973606.jfif\",\"/api/media/uploads/1786189823592-975828192.jfif\",\"/api/media/uploads/1786189823592-196127645.jfif\",\"/api/media/uploads/1786189823592-58687659.jpg\",\"/api/media/uploads/1786189823594-218748217.jpg\"]','[\"Khám phá mới\"]','admin','2026-10-06 22:07:56','approved'),('da-nang-chua-linh-ung','da-nang','Bán Đảo Sơn Trà & Chùa Linh Ứng','culture',5,'Tọa lạc trên bán đảo Sơn Trà xanh ngát với tượng Bồ Tát Quán Thế Âm cao 67m mặt hướng ra biển Đông, nơi hội tụ linh khí đất trời và phong cảnh non nước hữu tình.','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?w=800&q=80','[\"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?w=800&q=80\"]','[\"Tâm linh\",\"Biển trời\",\"Bán đảo Sơn Trà\",\"Đà Nẵng\"]','viet','2026-10-12 22:06:08','approved'),('danang-1','da-nang','Bà Nà Hills','entertainment',5,'Khu du lịch trên mây với Cầu Vàng nổi tiếng thế giới.','https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Ba_Na_Hills_French_Village.jpg/1280px-Ba_Na_Hills_French_Village.jpg','[]','[\"Giải trí\",\"Kiến trúc\",\"Núi\"]','admin','2026-10-06 22:07:56','approved'),('ha-giang-1786187463212','ha-giang','d','discovery',5,'d','/api/media/uploads/1786187463183-940900214.jpg','[\"/api/media/uploads/1786187463183-940900214.jpg\",\"/api/media/uploads/1786187463183-948683917.jpg\",\"/api/media/uploads/1786187463184-974820731.jpg\",\"/api/media/uploads/1786187463188-678817469.jpg\",\"/api/media/uploads/1786187463188-755448530.jpg\"]','[\"Khám phá mới\"]','admin','2026-10-06 22:07:56','approved'),('ha-giang-hem-tu-san-pending','ha-giang','Hẻm Tu Sản & Chèo Thuyền Sông Nho Quế','discovery',5,'Hẻm vực sâu nhất và hùng vĩ nhất Đông Nam Á với vách đá dựng đứng cao hơn 800m. Du khách có thể ngồi thuyền hoặc chèo kayak trên dòng nước xanh màu ngọc bích êm đềm dưới chân đèo Mã Pí Lèng.','https://images.unsplash.com/photo-1557750255-c76072a7aad1?w=800&q=80','[\"https://images.unsplash.com/photo-1557750255-c76072a7aad1?w=800&q=80\",\"https://images.unsplash.com/photo-1528127269322-539801943592?w=800&q=80\"]','[\"Hẻm Tu Sản\",\"Sông Nho Quế\",\"Khám phá\",\"Cảnh đẹp hùng vĩ\"]','viet','2026-10-12 22:06:08','pending'),('ha-nam-1791816328933','ha-nam','Chùa Tam Chúc','discovery',5,'Cảnh quan và Địa thế\nHồ Lục Nhạc: Mặt hồ rộng lớn có 6 hòn đảo nhỏ đá vôi nổi lên, tượng trưng cho 6 chiếc chuông. Trải nghiệm đi thuyền trên hồ mang lại cảm giác tĩnh lặng, tách biệt với nhịp sống bên ngoài.\n\nHệ sinh thái núi đá: Dãy núi đá vôi bao quanh tạo nên một vùng vi khí hậu mát mẻ. Khung cảnh đặc biệt hùng vĩ và có phần huyền ảo vào những buổi sáng sớm có sương mù.\n\nKiến trúc và Nghệ thuật\nVườn Cột Kinh: Điểm nhấn độc đáo với những cột đá xanh nguyên khối khổng lồ khắc kinh Phật, nặng hàng chục tấn, được lấy cảm hứng từ bảo vật quốc gia cột kinh chùa Nhất Trụ ở cố đô Hoa Lư.\n\nHệ thống ba điện chính: Du khách đi qua Điện Quan Âm, Điện Pháp Chủ và Điện Tam Thế theo cấu trúc bậc thang leo dần lên sườn núi. Các bức tường bên trong được ốp những bức phù điêu bằng đá núi lửa lấy từ Indonesia, ghép thủ công tỉ mỉ để kể lại các tích Phật.\n\nChùa Ngọc: Nằm trên đỉnh núi Thất Tinh ở độ cao 468m, ngôi chùa nhỏ này được lắp ghép hoàn toàn bằng các khối đá đỏ nguyên khối từ Ấn Độ mà không cần chất kết dính. Việc chinh phục gần 300 bậc thang đá dốc đứng để lên đến đây là một thử thách về thể lực, nhưng bù lại là tầm nhìn toàn cảnh ôm trọn quần thể.\n\nTrải nghiệm Thực tế\nViệc tham quan Tam Chúc đòi hỏi sự chuẩn bị tốt về thể lực và thời gian vì không gian cực kỳ rộng lớn. Bạn sẽ phải kết hợp nhiều loại hình di chuyển từ thuyền, xe điện cho đến đi bộ đường dài. Vào mùa lễ hội đầu xuân, khu vực này thường xuyên đối mặt với tình trạng quá tải, làm giảm đi đáng kể sự thanh tịnh vốn có của không gian tâm linh.\n\nĐối với một nền tảng khám phá và hỗ trợ lập kế hoạch du lịch tích hợp trí tuệ nhân tạo, một siêu quần thể như Tam Chúc là một bài toán phân tích dữ liệu rất điển hình. Thuật toán sẽ cần xử lý các biến số đa phương thức như việc kết hợp thời gian chờ thuyền, tuyến đường xe điện, giới hạn thể lực khi leo bậc thang lên Chùa Ngọc, và mật độ du khách biến động theo mùa để tối ưu hóa một lộ trình tham quan thực tế.','/api/media/uploads/1791816328764-578545042.jfif','[\"/api/media/uploads/1791816328764-578545042.jfif\",\"/api/media/uploads/1791816328766-639831864.jfif\",\"/api/media/uploads/1791816328766-493672.jfif\"]','[\"Khám phá mới\"]','ngocanh','2026-10-12 21:45:28','approved'),('ha-nam-1791816451043','ha-nam','Chùa Phật Quang','discovery',5,'1. Không gian ngoại cảnh mang đậm chất thiền (Zen)\nBước vào chùa, du khách thường bị ấn tượng mạnh bởi khuôn viên được thiết kế tỉ mỉ như một bức tranh thủy mặc. Lối đi rải sỏi trắng muốt xen kẽ những phiến đá bước dặm lớn, kết hợp với hồ nước trong xanh, lầu trà và những chậu bonsai được tạo dáng cầu kỳ [1.1.3, 1.1.4]. Cách quy hoạch tiểu cảnh này mang hơi hướng của các khu vườn thiền Nhật Bản, chú trọng vào từng chi tiết nhỏ để tạo ra sự tĩnh lặng tuyệt đối cho tâm hồn [1.1.4].\n\n2. Dấu ấn thư pháp tiếng Việt\nMột điểm nhấn mang đậm bản sắc văn hóa và tính giáo dục tại chùa Phật Quang là hệ thống hoành phi, câu đối hay những dòng chữ khắc trên các phiến đá đều được viết bằng thư pháp tiếng Việt [1.1.3]. Những nét chữ mềm mại, bay bổng này phần lớn do chính tay sư trụ trì chắp bút [1.1.4, 1.1.7]. Việc sử dụng tiếng Việt giúp du khách và Phật tử ở mọi lứa tuổi dễ dàng đọc, hiểu và cảm thụ trực tiếp các triết lý Phật pháp.\n\n3. Kiến trúc nội tự trang nhã và ấm cúng\nThay vì những khối bêtông khổng lồ, các không gian thờ tự tại đây (như Tam Bảo, nhà Tổ) có thiết kế đơn giản nhưng vô cùng tinh xảo [1.1.3, 1.1.4]. Các bức tượng Phật bằng gỗ được chạm khắc công phu [1.1.3]. Không gian bên trong kết hợp ánh sáng ấm áp từ những chiếc đèn lồng cùng hoa tươi và cây xanh, tạo cảm giác vô cùng thanh lịch, gần gũi và trang nghiêm [1.1.5, 1.1.7].\n\nGóc nhìn về thiết kế lộ trình du lịch:\nTrong bối cảnh bạn đang phát triển nền tảng AI hỗ trợ lập kế hoạch du lịch, chùa Phật Quang là một điểm đến mang tính \"cân bằng\" rất tốt cho tuyến Hà Nam. Nếu du khách đã dành buổi sáng tại Tam Chúc để đi bộ, leo núi và choáng ngợp trước sự vĩ đại của thiên nhiên, thì chùa Phật Quang chính là điểm dừng chân lý tưởng vào buổi chiều. Nơi đây phù hợp để đưa vào thuật toán như một điểm \"nghỉ ngơi tâm lý\" – nơi người dùng có thể ngồi uống trà, ngắm cá Koi, nghe chim hót và sống chậm lại sau một hành trình dài.','/api/media/uploads/1791816450905-607878950.jfif','[\"/api/media/uploads/1791816450905-607878950.jfif\",\"/api/media/uploads/1791816450906-499051916.jfif\",\"/api/media/uploads/1791816450907-585575514.jfif\",\"/api/media/uploads/1791816450908-406688870.jfif\"]','[\"Khám phá mới\"]','ngocanh','2026-10-12 21:47:31','approved'),('ha-nam-1791816555655','ha-nam','Làng Vũ Đại','discovery',5,'1. Không gian ngoại cảnh mang đậm chất thiền (Zen)\nBước vào chùa, du khách thường bị ấn tượng mạnh bởi khuôn viên được thiết kế tỉ mỉ như một bức tranh thủy mặc. Lối đi rải sỏi trắng muốt xen kẽ những phiến đá bước dặm lớn, kết hợp với hồ nước trong xanh, lầu trà và những chậu bonsai được tạo dáng cầu kỳ [1.1.3, 1.1.4]. Cách quy hoạch tiểu cảnh này mang hơi hướng của các khu vườn thiền Nhật Bản, chú trọng vào từng chi tiết nhỏ để tạo ra sự tĩnh lặng tuyệt đối cho tâm hồn [1.1.4].\n\n2. Dấu ấn thư pháp tiếng Việt\nMột điểm nhấn mang đậm bản sắc văn hóa và tính giáo dục tại chùa Phật Quang là hệ thống hoành phi, câu đối hay những dòng chữ khắc trên các phiến đá đều được viết bằng thư pháp tiếng Việt [1.1.3]. Những nét chữ mềm mại, bay bổng này phần lớn do chính tay sư trụ trì chắp bút [1.1.4, 1.1.7]. Việc sử dụng tiếng Việt giúp du khách và Phật tử ở mọi lứa tuổi dễ dàng đọc, hiểu và cảm thụ trực tiếp các triết lý Phật pháp.\n\n3. Kiến trúc nội tự trang nhã và ấm cúng\nThay vì những khối bêtông khổng lồ, các không gian thờ tự tại đây (như Tam Bảo, nhà Tổ) có thiết kế đơn giản nhưng vô cùng tinh xảo [1.1.3, 1.1.4]. Các bức tượng Phật bằng gỗ được chạm khắc công phu [1.1.3]. Không gian bên trong kết hợp ánh sáng ấm áp từ những chiếc đèn lồng cùng hoa tươi và cây xanh, tạo cảm giác vô cùng thanh lịch, gần gũi và trang nghiêm [1.1.5, 1.1.7].\n\nGóc nhìn về thiết kế lộ trình du lịch:\nTrong bối cảnh bạn đang phát triển nền tảng AI hỗ trợ lập kế hoạch du lịch, chùa Phật Quang là một điểm đến mang tính \"cân bằng\" rất tốt cho tuyến Hà Nam. Nếu du khách đã dành buổi sáng tại Tam Chúc để đi bộ, leo núi và choáng ngợp trước sự vĩ đại của thiên nhiên, thì chùa Phật Quang chính là điểm dừng chân lý tưởng vào buổi chiều. Nơi đây phù hợp để đưa vào thuật toán như một điểm \"nghỉ ngơi tâm lý\" – nơi người dùng có thể ngồi uống trà, ngắm cá Koi, nghe chim hót và sống chậm lại sau một hành trình dài.','/api/media/uploads/1791816555526-607312369.jfif','[\"/api/media/uploads/1791816555526-607312369.jfif\",\"/api/media/uploads/1791816555526-157964808.jfif\",\"/api/media/uploads/1791816555528-410323841.jfif\",\"/api/media/uploads/1791816555536-358124984.jfif\"]','[\"Khám phá mới\"]','viet','2026-10-12 21:49:15','approved'),('ha-nam-1791958192593','ha-nam','Tam Chúc','discovery',5,'abc','/api/media/uploads/1791958192247-581595722.jpg','[\"/api/media/uploads/1791958192247-581595722.jpg\",\"/api/media/uploads/1791958192249-710770227.jpg\",\"/api/media/uploads/1791958192251-419650112.jpg\"]','[\"Khám phá mới\"]','ngocanh','2026-10-14 13:09:52','approved'),('ha-noi-1791303238881','ha-noi','Cầu Long Biên Lịch Sử','discovery',5,'Cây cầu bắc qua sông Hồng chứng nhân của biết bao thăng trầm lịch sử thủ đô.','https://images.unsplash.com/photo-1509316785289-025f5b846b35?w=800&q=80','[\"https://images.unsplash.com/photo-1509316785289-025f5b846b35?w=800&q=80\"]','[]','1.đoànngọcanh823','2026-10-06 23:13:58','approved'),('ha-noi-1791816844258','ha-noi','Văn Miếu Quốc Tử Giám','discovery',5,'Kiến trúc và Không gian\n\nBố cục phân lớp: Quần thể được chia thành 5 khu vực không gian liên tiếp theo trục Bắc - Nam, dẫn dắt người xem qua các cổng Đại Trung, Khuê Văn Các (biểu tượng của Hà Nội) cho đến khu điện thờ Đại Thành và nhà Thái Học. Sự phân lớp này tạo ra một nhịp điệu tĩnh lặng dần khi càng tiến sâu vào bên trong.\n\nVườn Bia Tiến sĩ: 82 tấm bia đá đặt trên lưng rùa ghi danh các vị khoa bảng là một di sản tư liệu vô giá. Khu vực này không chỉ là nơi lưu giữ lịch sử mà còn là biểu tượng mạnh mẽ của tinh thần hiếu học.\n\nHệ sinh thái cổ thụ: Những tán cây đa, cây muỗm hàng trăm năm tuổi bao quanh giếng Thiên Quang Tỉnh tạo ra một vùng vi khí hậu mát mẻ, thanh bình, tách biệt hoàn toàn với nhịp sống hối hả trên các tuyến phố Tôn Đức Thắng hay Quốc Tử Giám bên ngoài tường gạch.\n\nGóc nhìn về cấu trúc dữ liệu cho AI Travel Planner\nKhi mô hình hóa dữ liệu Điểm đến (POI) cho một nền tảng lập kế hoạch du lịch thông minh, Văn Miếu - Quốc Tử Giám là một \"nút\" (node) trọng yếu tại Hà Nội với các thuộc tính rất chuẩn hóa:\n\nTối ưu hóa lộ trình (Routing): Nhờ vị trí trung tâm, thuật toán có thể dễ dàng ghép nối Văn Miếu với Hoàng Thành Thăng Long, Bảo tàng Mỹ thuật hoặc Lăng Bác để tạo thành một tuyến City Tour văn hóa nửa ngày tối ưu về mặt di chuyển.\n\nPhân loại người dùng (User Profiling): Đây là điểm đến có độ \"khớp\" (match) rất cao với nhiều tệp khách: từ khách quốc tế muốn tìm hiểu văn hóa phương Đông, cho đến học sinh, sinh viên tại Hà Nội ghé thăm để cầu may mắn trước mỗi kỳ thi hay chụp ảnh kỷ yếu.\n\nĐịnh mức thời gian (Time Allocation): Thời lượng tham quan lý tưởng (dwell time) thường được thiết lập từ 60 - 90 phút. Địa hình tại đây bằng phẳng hoàn toàn, là một thông số lý tưởng khi hệ thống tính toán năng lượng tiêu hao cho những nhóm du khách không muốn đi bộ leo dốc nhiều như ở Tam Chúc.','/api/media/uploads/1791816844109-360114745.jfif','[\"/api/media/uploads/1791816844109-360114745.jfif\",\"/api/media/uploads/1791816844110-379132080.jfif\",\"/api/media/uploads/1791816844111-669200490.jfif\",\"/api/media/uploads/1791816844112-552868757.jfif\"]','[\"Khám phá mới\"]','admin','2026-10-12 21:54:04','approved'),('hai-phong-1786183735201','hai-phong','d','discovery',5,'d','/api/media/uploads/1786183735108-114118906.jpg','[\"/api/media/uploads/1786183735108-114118906.jpg\"]','[\"Khám phá mới\"]','admin','2026-10-06 22:07:56','approved'),('halong-1','quang-ninh','Vịnh Hạ Long','nature',5,'Di sản thiên nhiên thế giới với hàng ngàn hòn đảo đá vôi kỳ vĩ.','https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/V%E1%BB%8Bnh_H%E1%BA%A1_Long_-_NKS.jpg/1280px-V%E1%BB%8Bnh_H%E1%BA%A1_Long_-_NKS.jpg?utm_source=vi.wikipedia.org&utm_campaign=api&utm_content=thumbnail','[\"https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/V%E1%BB%8Bnh_H%E1%BA%A1_Long_-_NKS.jpg/1280px-V%E1%BB%8Bnh_H%E1%BA%A1_Long_-_NKS.jpg?utm_source=vi.wikipedia.org&utm_campaign=api&utm_content=thumbnail\"]','[\"Di sản UNESCO\",\"Thiên nhiên\",\"Biển đảo\"]','admin','2026-10-06 22:07:56','approved'),('hanoi-1','ha-noi','Hồ Hoàn Kiếm','culture',5,'Trái tim của thủ đô, nơi lưu giữ truyền thuyết gươm thần và rùa vàng.','https://upload.wikimedia.org/wikipedia/commons/1/1c/Hoan_Kiem.jpg?utm_source=vi.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled','[\"https://upload.wikimedia.org/wikipedia/commons/1/1c/Hoan_Kiem.jpg?utm_source=vi.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled\"]','[\"Văn hóa\",\"Lịch sử\",\"Biểu tượng\"]','admin','2026-10-06 22:07:56','approved'),('hcm-1','tp-hcm','Chợ Bến Thành','culture',4,'Biểu tượng giao thương lâu đời và sầm uất của Sài Gòn.','https://upload.wikimedia.org/wikipedia/commons/9/91/Ben_Thanh_market_2.jpg?utm_source=vi.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled','[\"https://upload.wikimedia.org/wikipedia/commons/9/91/Ben_Thanh_market_2.jpg?utm_source=vi.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled\"]','[\"Mua sắm\",\"Lịch sử\",\"Ẩm thực\"]','admin','2026-10-06 22:07:56','approved'),('hcm-2','tp-hcm','Dinh Độc Lập','history',5,'Di tích lịch sử quan trọng, nơi đánh dấu sự thống nhất đất nước.','https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Dinh_%C4%90%E1%BB%99c_L%E1%BA%ADp_v%C3%A0o_n%C3%A0m_2024.jpg/1280px-Dinh_%C4%90%E1%BB%99c_L%E1%BA%ADp_v%C3%A0o_n%C3%A0m_2024.jpg?utm_source=vi.wikipedia.org&utm_campaign=api&utm_content=thumbnail','[\"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Dinh_%C4%90%E1%BB%99c_L%E1%BA%ADp_v%C3%A0o_n%C3%A0m_2024.jpg/1280px-Dinh_%C4%90%E1%BB%99c_L%E1%BA%ADp_v%C3%A0o_n%C3%A0m_2024.jpg?utm_source=vi.wikipedia.org&utm_campaign=api&utm_content=thumbnail\"]','[\"Lịch sử\",\"Kiến trúc\",\"Tham quan\"]','admin','2026-10-06 22:07:56','approved'),('hue-chua-thien-mu','thua-thien-hue','Chùa Thiên Mụ & Tháp Phước Duyên','culture',5,'Ngôi đệ nhất cổ tự xứ Huế tọa lạc trên đồi Hà Khê soi bóng xuống dòng sông Hương hiền hòa, với ngọn tháp Phước Duyên 7 tầng hình bát giác uy nghi trầm mặc.','https://images.unsplash.com/photo-1548013146-72479768bada?w=800&q=80','[\"https://images.unsplash.com/photo-1548013146-72479768bada?w=800&q=80\"]','[\"Tâm linh\",\"Văn hóa\",\"Sông Hương\",\"Cổ tự\"]','ngocanh','2026-10-12 22:06:08','approved'),('hue-dai-noi','thua-thien-hue','Đại Nội Huế - Hoàng thành Cố Đô','history',5,'Kinh đô của vương triều nhà Nguyễn suốt 143 năm, quần thể di tích kiến trúc cung đình vàng son nguy nga gồm Ngọ Môn, Điện Thái Hòa, Tử Cấm Thành mang đậm hồn cốt dân tộc.','https://images.unsplash.com/photo-1573492534282-c9a32f59cf56?w=800&q=80','[\"https://images.unsplash.com/photo-1573492534282-c9a32f59cf56?w=800&q=80\",\"https://images.unsplash.com/photo-1548013146-72479768bada?w=800&q=80\"]','[\"Di sản UNESCO\",\"Lịch sử\",\"Kiến trúc\",\"Cung đình\"]','admin','2026-10-12 22:06:08','approved'),('khanh-hoa-thap-ba-ponagar','khanh-hoa','Tháp Bà Ponagar Nha Trang','history',5,'Kiệt tác kiến trúc và điêu khắc đất nung của nền văn hóa Chăm Pa cổ xưa, ngự trên ngọn đồi nhỏ lộng gió nhìn ra cửa biển Nha Trang xanh biếc hiền hòa.','https://images.unsplash.com/photo-1544644181-1484b3fdfc62?w=800&q=80','[\"https://images.unsplash.com/photo-1544644181-1484b3fdfc62?w=800&q=80\"]','[\"Văn hóa Chăm Pa\",\"Di tích lịch sử\",\"Kiến trúc cổ\",\"Nha Trang\"]','admin','2026-10-12 22:06:08','approved'),('kien-giang-bai-sao','kien-giang','Bãi Sao Phú Quốc','nature',5,'Bãi biển đẹp tựa thiên đường với dải cát trắng mịn màng như kem sữa uốn lượn hình cánh cung ôm lấy làn nước biển ngọc bích êm đềm và hàng dừa nghiêng bóng.','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80','[\"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80\"]','[\"Biển đảo\",\"Nghỉ dưỡng\",\"Cát trắng\",\"Phú Quốc\"]','admin','2026-10-12 22:06:08','approved'),('lam-dong-thac-datanla','lam-dong','Khu Du Lịch Thác Datanla Đà Lạt','entertainment',5,'Dòng thác bọt tung trắng xóa ẩn mình giữa hẻm sâu rừng thông nguyên sinh, trải nghiệm hệ thống máng trượt uốn lượn xuyên rừng thông dài nhất Đông Nam Á.','https://images.unsplash.com/photo-1528360983277-13d401cdc186?w=800&q=80','[\"https://images.unsplash.com/photo-1528360983277-13d401cdc186?w=800&q=80\"]','[\"Thác nước\",\"Mạo hiểm\",\"Máng trượt\",\"Đà Lạt\"]','admin','2026-10-12 22:06:08','approved'),('lamdong-1','lam-dong','Hồ Xuân Hương','nature',5,'Trái tim lãng mạn của thành phố ngàn hoa Đà Lạt.','https://upload.wikimedia.org/wikipedia/commons/0/05/Ho_Xuan_Huong.png?utm_source=vi.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled','[\"https://upload.wikimedia.org/wikipedia/commons/0/05/Ho_Xuan_Huong.png?utm_source=vi.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled\"]','[\"Thiên nhiên\",\"Lãng mạn\",\"Thư giãn\"]','admin','2026-10-06 22:07:56','approved'),('lao-cai-ban-cat-cat-pending','lao-cai','Bản Cát Cát - Bản Cổ Đẹp Mộng Mơ Giữa Núi Rừng Sa Pa','culture',5,'Ngôi làng cổ kính của đồng bào người H\'Mông nằm yên bình dưới chân đỉnh Fansipan. Bản làng thu hút du khách bởi những nếp nhà gỗ truyền thống, cối xay nước khổng lồ và dòng thác Tiên Sa róc rách thơ mộng.','https://images.unsplash.com/photo-1509316785289-025f5b846b35?w=800&q=80','[\"https://images.unsplash.com/photo-1509316785289-025f5b846b35?w=800&q=80\"]','[\"Bản làng\",\"Văn hóa H\'Mông\",\"Check-in\",\"Sa Pa\"]','ngocanh','2026-10-12 22:06:08','rejected'),('laocai-1','lao-cai','Đỉnh Fansipan','nature',5,'Nóc nhà Đông Dương, nơi chinh phục những đám mây.','https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Fansipan_summit.jpg/1280px-Fansipan_summit.jpg','[]','[\"Núi\",\"Khám phá\",\"Cáp treo\"]','admin','2026-10-06 22:07:56','approved'),('ninh-binh-hang-mua','ninh-binh','Hang Múa & Đỉnh Ngọa Long','nature',5,'Chinh phục gần 500 bậc thang đá uốn lượn lên đỉnh núi Ngọa Long để phóng tầm mắt ngắm trọn toàn cảnh thung lũng Tam Cốc và sông Ngô Đồng mùa lúa chín vàng ươm.','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80','[\"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80\"]','[\"Check-in\",\"Leo núi\",\"Toàn cảnh đẹp\",\"Nhiếp ảnh\"]','viet','2026-10-12 22:06:08','approved'),('ninh-binh-trang-an','ninh-binh','Quần thể danh thắng Tràng An','nature',5,'Di sản Văn hóa và Thiên nhiên thế giới được UNESCO công nhận với cảnh quan karst tháp đá vôi ngoạn mục, hang động ngập nước kỳ bí và những dòng sông thơ mộng.','https://images.unsplash.com/photo-1528127269322-539801943592?w=800&q=80','[\"https://images.unsplash.com/photo-1528127269322-539801943592?w=800&q=80\",\"https://images.unsplash.com/photo-1509316785289-025f5b846b35?w=800&q=80\"]','[\"Di sản UNESCO\",\"Thiên nhiên\",\"Hang động\",\"Chèo thuyền\"]','admin','2026-10-12 22:06:08','approved'),('quang-binh-dong-phong-nha','quang-binh','Động Phong Nha - Vườn Quốc Gia Phong Nha Kẻ Bàng','nature',5,'Kỳ quan đệ nhất động ngầm thế giới với dòng sông ngầm kỳ ảo, bãi cát trong hang và những măng đá, nhũ đá thạch cao óng ánh như ngọc bích.','https://images.unsplash.com/photo-1557750255-c76072a7aad1?w=800&q=80','[\"https://images.unsplash.com/photo-1557750255-c76072a7aad1?w=800&q=80\"]','[\"Di sản UNESCO\",\"Kỳ quan thiên nhiên\",\"Hang động kỳ vĩ\",\"Quảng Bình\"]','viet','2026-10-12 22:06:08','approved'),('quang-ninh-1791388992353','quang-ninh','Chùa Ba Vàng','discovery',5,'Chùa Ba Vàng (còn gọi là Bảo Quang Tự) là một ngôi chùa tọa lạc ở lưng chừng núi Thành Đẳng, thuộc phường Uông Bí, thành phố Quảng Ninh.\nChùa nằm trên sườn núi Thành Đẳng, nhìn hướng mặt ra phía Tây là trung tâm phường Uông Bí, phía trước là Bạch Đằng giang, xa xa là thành phố cảng Hải Phòng, hút tầm mắt là biển Đồ Sơn. Bên trái là những dãy núi Thanh Long trùng điệp chầu về, bên phải là những dãy núi Bạch Hổ hùng vĩ phục xuống.\nNăm 2007, được sự chấp thuận của chính quyền và sự cho phép của Hòa thượng Thích Thanh Từ (Viện chủ Thiền viện Trúc Lâm), Đại đức Thích Trúc Thái Minh nhận trách nhiệm trụ trì chùa Ba Vàng.[3] Ngày 9 tháng 3 năm 2014, Giáo hội Phật giáo Việt Nam tuyên bố khánh thành chùa Ba Vàng.[4][5][6] Ngày 16 tháng 9 năm 2014, chùa Ba Vàng tuyên bố khánh thành Nhà thờ Tam Tổ Trúc Lâm và đại tượng A-di-đà.[7] Chùa Ba Vàng dưới sự trụ trì của Đại đức Thích Trúc Thái Minh đến nay đã phát triển thêm các chùa chi nhánh và chùa trực thuộc bao gồm: Chùa Thiên Lai, Chùa Diên Phúc[8] và Chùa Đế Thích.','/api/media/uploads/1791388992276-560907623.png','[\"/api/media/uploads/1791388992276-560907623.png\"]','[\"Khám phá mới\"]','viet','2026-10-07 23:03:12','rejected'),('quang-ninh-1791389142262','quang-ninh','Chùa Ba Vàng','discovery',5,'Chùa Ba Vàng (còn gọi là Bảo Quang Tự) là một ngôi chùa tọa lạc ở lưng chừng núi Thành Đẳng, thuộc phường Uông Bí, thành phố Quảng Ninh.\nChùa nằm trên sườn núi Thành Đẳng, nhìn hướng mặt ra phía Tây là trung tâm phường Uông Bí, phía trước là Bạch Đằng giang, xa xa là thành phố cảng Hải Phòng, hút tầm mắt là biển Đồ Sơn. Bên trái là những dãy núi Thanh Long trùng điệp chầu về, bên phải là những dãy núi Bạch Hổ hùng vĩ phục xuống.\nNăm 2007, được sự chấp thuận của chính quyền và sự cho phép của Hòa thượng Thích Thanh Từ (Viện chủ Thiền viện Trúc Lâm), Đại đức Thích Trúc Thái Minh nhận trách nhiệm trụ trì chùa Ba Vàng.[3] Ngày 9 tháng 3 năm 2014, Giáo hội Phật giáo Việt Nam tuyên bố khánh thành chùa Ba Vàng.[4][5][6] Ngày 16 tháng 9 năm 2014, chùa Ba Vàng tuyên bố khánh thành Nhà thờ Tam Tổ Trúc Lâm và đại tượng A-di-đà.[7] Chùa Ba Vàng dưới sự trụ trì của Đại đức Thích Trúc Thái Minh đến nay đã phát triển thêm các chùa chi nhánh và chùa trực thuộc bao gồm: Chùa Thiên Lai, Chùa Diên Phúc[8] và Chùa Đế Thích.','/api/media/uploads/1791389142206-926555361.png','[\"/api/media/uploads/1791389142206-926555361.png\"]','[\"Khám phá mới\"]','viet','2026-10-07 23:05:42','approved'),('quang-ninh-1791561324002','quang-ninh','Chùa Ba Vàng','discovery',5,'Chùa Ba Vàng là một ngôi chùa tọa lạc ở lưng chừng núi Thành Đẳng, thuộc phường Uông Bí, thành phố Quảng Ninh.','/api/media/uploads/1791561323957-365198576.jpg','[\"/api/media/uploads/1791561323957-365198576.jpg\",\"/api/media/uploads/1791561323958-609194405.jpg\"]','[\"Khám phá mới\"]','1.đoànngọcanh823','2026-10-09 22:55:24','pending'),('quang-ninh-bao-tang-pending','quang-ninh','Bảo Tàng Quảng Ninh - Khối Kim Cương Đen Bên Vịnh','culture',5,'Kiệt tác kiến trúc hiện đại được ví như khối than đá khổng lồ phản chiếu mây trời Hạ Long. Không gian trưng bày kết hợp hiện đại giới thiệu sinh thái biển, lịch sử khai mỏ than và cổ vật văn hóa Đông Triều - Yên Tử.','https://images.unsplash.com/photo-1583417319070-4a69db38a482?w=800&q=80','[\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?w=800&q=80\"]','[\"Bảo tàng\",\"Kiến trúc độc đáo\",\"Check-in\",\"Hạ Long\"]','1.đoànngọcanh823','2026-10-12 22:06:08','pending'),('quangnam-1','quang-nam','Phố cổ Hội An','culture',5,'Thương cảng sầm uất xưa, nay là đô thị cổ lung linh dưới ánh đèn lồng.','https://upload.wikimedia.org/wikipedia/commons/f/f3/PhoCoHoiAn.jpg?utm_source=vi.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled','[\"https://upload.wikimedia.org/wikipedia/commons/f/f3/PhoCoHoiAn.jpg?utm_source=vi.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled\"]','[\"Di sản UNESCO\",\"Văn hóa\",\"Kiến trúc cổ\"]','admin','2026-10-06 22:07:56','approved'),('tay-ninh-nui-ba-den-pending','tay-ninh','Quần Thể Núi Bà Đen - Nóc Nhà Nam Bộ','discovery',5,'Đỉnh núi Bà Đen cao 986m được mệnh danh là Nóc nhà Nam Bộ, nổi tiếng với hệ thống cáp treo hiện đại, khí hậu mát mẻ và đại tượng Phật Bà Tây Bổ Đà Sơn bằng đồng uy nghiêm giữa biển mây bồng bềnh.','https://images.unsplash.com/photo-1599707367072-cd6ada2bc375?w=800&q=80','[\"https://images.unsplash.com/photo-1599707367072-cd6ada2bc375?w=800&q=80\"]','[\"Nóc nhà Nam Bộ\",\"Săn mây\",\"Tâm linh\",\"Cáp treo\"]','1.đoànngọcanh823','2026-10-12 22:06:08','pending');
